// Pure renderers for every generated file. No I/O here; scripts/catalog.mjs
// does the reading and writing so these stay trivially testable.

export const PLUGIN_NAME = 'anguspiv-skills';
export const OWNER = { name: 'Angus Perkerson', url: 'https://github.com/anguspiv' };
export const GENERATED = 'generated by scripts/catalog.mjs — do not edit by hand';

const json = (obj) => JSON.stringify(obj, null, 2) + '\n';

function summary(skills) {
  if (!skills.length) return 'Skills for AI coding agents by anguspiv.';
  return `Skills for AI coding agents by anguspiv: ${skills.map((s) => s.name).join(', ')}.`;
}

export function renderPluginJson({ version, skills, repo }) {
  return json({
    $schema: 'https://anthropic.com/claude-code/plugin.schema.json',
    name: PLUGIN_NAME,
    displayName: 'anguspiv skills',
    version,
    description: summary(skills),
    author: { name: OWNER.name, email: 'angusp@angusp.com', url: OWNER.url },
    homepage: `https://${repo.split('/')[0]}.github.io/${repo.split('/')[1]}/`,
    repository: `https://github.com/${repo}`,
    license: 'MIT',
    keywords: ['agent-skills', 'claude-code', 'skills', ...skills.map((s) => s.name)],
    metadata: { generated: GENERATED },
  });
}

export function renderMarketplaceJson({ skills, repo }) {
  return json({
    $schema: 'https://anthropic.com/claude-code/marketplace.schema.json',
    name: PLUGIN_NAME,
    description: 'Skills for AI coding agents by anguspiv',
    owner: OWNER,
    plugins: [
      {
        name: PLUGIN_NAME,
        source: './',
        description: summary(skills),
        category: 'development',
        keywords: ['agent-skills', 'skills', ...skills.map((s) => s.name)],
      },
    ],
  });
}

export function renderReadmeTable(skills) {
  if (!skills.length) return '_No skills yet. See [docs/ideas.md](docs/ideas.md) for what is coming._';
  const rows = skills.map((s) => `| [${s.name}](skills/${s.name}) | ${s.data.metadata.version} | ${s.data.description.replace(/\|/g, '\\|')} |`);
  return ['| Skill | Version | Use when |', '| --- | --- | --- |', ...rows].join('\n');
}

export function replaceBetweenMarkers(text, start, end, inner) {
  const a = text.indexOf(start);
  const b = text.indexOf(end);
  if (a === -1 || b === -1 || b < a) throw new Error(`markers ${start} … ${end} not found`);
  return text.slice(0, a + start.length) + '\n' + inner + '\n' + text.slice(b);
}

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

export function renderIndexHtml({ version, skills, repo }) {
  const cards = skills.length
    ? skills
        .map(
          (s) => `      <article class="card" id="${esc(s.name)}">
        <h3><a href="https://github.com/${repo}/tree/main/skills/${esc(s.name)}">${esc(s.name)}</a> <span class="v">v${esc(s.data.metadata.version)}</span></h3>
        <p>${esc(s.data.description)}</p>
        <pre><code>npx skills add ${repo}@${esc(s.name)}</code></pre>
      </article>`,
        )
        .join('\n')
    : '      <p class="empty">No skills published yet. See the <a href="https://github.com/' + repo + '/blob/main/docs/ideas.md">ideas backlog</a>.</p>';

  return `<!doctype html>
<!-- ${GENERATED} -->
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>agent-skills</title>
  <meta name="description" content="Skills for AI coding agents by anguspiv, installable via the Claude Code plugin marketplace and skills.sh.">
  <style>
    :root { --bg: #fff; --fg: #1a1a1a; --muted: #666; --line: #e5e5e5; --code: #f4f4f4; --accent: #2563eb; }
    @media (prefers-color-scheme: dark) { :root { --bg: #111; --fg: #eee; --muted: #999; --line: #333; --code: #1c1c1c; --accent: #60a5fa; } }
    * { box-sizing: border-box; }
    body { margin: 0; padding: 0 16px 48px; background: var(--bg); color: var(--fg); font: 16px/1.5 system-ui, -apple-system, Segoe UI, sans-serif; }
    main { max-width: 760px; margin: 0 auto; }
    h1 { margin: 40px 0 4px; font-size: 2rem; } h1 + p { margin-top: 0; color: var(--muted); }
    h2 { margin-top: 40px; font-size: 1.25rem; }
    pre { background: var(--code); border: 1px solid var(--line); border-radius: 6px; padding: 10px 12px; overflow-x: auto; margin: 8px 0; }
    code { font: 0.9em ui-monospace, SFMono-Regular, Menlo, monospace; }
    .card { border: 1px solid var(--line); border-radius: 8px; padding: 16px; margin: 12px 0; }
    .card h3 { margin: 0 0 6px; font-size: 1.1rem; } .card p { margin: 0 0 8px; }
    .v { font-size: 0.8rem; color: var(--muted); font-weight: normal; }
    a { color: var(--accent); } .empty { color: var(--muted); }
    footer { margin-top: 48px; color: var(--muted); font-size: 0.9rem; }
  </style>
</head>
<body>
  <main>
    <h1>agent-skills</h1>
    <p>Skills for AI coding agents by <a href="${OWNER.url}">anguspiv</a>. Plugin v${esc(version)}.</p>

    <h2>Install everything</h2>
    <pre><code># Claude Code
claude plugin marketplace add ${repo}
claude plugin install ${PLUGIN_NAME}@${PLUGIN_NAME}

# skills.sh (Claude Code, Cursor, Codex, OpenCode, …)
npx skills add ${repo}</code></pre>

    <h2>Skills</h2>
${cards}

    <footer>
      <a href="https://github.com/${repo}">Source</a> ·
      <a href="https://github.com/${repo}/releases">Releases</a> ·
      <a href="https://github.com/${repo}/discussions">Discussions</a> ·
      MIT
    </footer>
  </main>
</body>
</html>
`;
}

export function bumpVersion(version, kind) {
  const [major, minor, patch] = version.split('.').map(Number);
  switch (kind) {
    case 'patch': return `${major}.${minor}.${patch + 1}`;
    case 'minor': return `${major}.${minor + 1}.0`;
    case 'major': return `${major + 1}.0.0`;
    default: throw new Error(`bump kind must be patch, minor, or major, got "${kind}"`);
  }
}

export function bumpSkillFile(text, kind) {
  let done = false;
  const out = text.replace(/^(\s+version:\s*["']?)(\d+\.\d+\.\d+)(["']?\s*)$/m, (_, pre, v, post) => {
    done = true;
    return `${pre}${bumpVersion(v, kind)}${post}`;
  });
  if (!done) throw new Error('no metadata.version line found');
  return out;
}
